function onMessage(m){
 if(m.type==='windowState'){const button=$('[data-window="maximize"]');button?.setAttribute('aria-pressed',String(m.maximized));button?.setAttribute('aria-label',m.maximized?'Восстановить':'Развернуть');return;}
 if(m.type==='reply'){const p=pending.get(m.id);if(p){pending.delete(m.id);m.ok?p.resolve(m.result):p.reject(new Error(m.error));}return;}
 if(m.type==='auth'){if(!$('#boot').hidden)$('#bootStatus').textContent=m.message;if(m.state==='waiting')$('#status').textContent='Ожидаем Microsoft';return;}
 if(m.type==='transferComplete'){$('#status').textContent=state.running.length?'Minecraft запущен':'Готов к приключениям';$('#progressText').textContent='';$('#progressBar').style.width='0%';$('#progressTrack').classList.remove('indeterminate');return;}
 if(m.type==='progress'){if(sourceUpdateRunning){$('#updateDetail').textContent=(m.message||'Подготовка')+(m.downloadedBytes!=null?' · '+bytes(m.downloadedBytes)+' / '+(m.totalBytes>0?bytes(m.totalBytes)+' · осталось '+bytes(Math.max(0,m.totalBytes-m.downloadedBytes)):'размер неизвестен'):'');$('#updateTrack').classList.toggle('indeterminate',!(m.percent>0));$('#updateBar').style.width=Math.max(0,Math.min(100,m.percent||0))+'%';}$('#status').textContent='Загрузка';$('#progressText').textContent=(m.message||'Подготовка')+(m.downloadedBytes!=null?' · '+bytes(m.downloadedBytes)+' / '+(m.totalBytes>0?bytes(m.totalBytes):'размер неизвестен')+(m.scope==='file'?' · текущий файл':' · текущий этап'):'');$('#progressTrack').classList.toggle('indeterminate',m.downloadedBytes!=null&&!(m.totalBytes>0));$('#progressBar').style.width=Math.max(0,Math.min(100,m.percent||0))+'%';return;}
 if(m.type==='logBatch'){for(const item of m.items||[])onMessage(item);return;}
 if(m.type==='log'){const a=logs.get(m.instanceId)||[];a.push(m.line);if(a.length>5000)a.splice(0,a.length-5000);logs.set(m.instanceId,a);if(editorId===m.instanceId&&editorTab==='logs')scheduleLogPaint(m.instanceId);return;}
 if(m.type==='started'){busy.delete(m.instanceId);state.running=[...new Set([...state.running,m.instanceId])];$('#status').textContent='Minecraft запущен';$('#progressText').textContent='';$('#progressBar').style.width='0%';syncPlayButtons();if(editorId===m.instanceId)renderEditor();return;}
 if(m.type==='exited'){state.running=state.running.filter(x=>x!==m.instanceId);toast(`Игра закрыта · код ${m.code}`);$('#status').textContent='Готов к приключениям';syncPlayButtons();if(editorId===m.instanceId)renderEditor();}
}
let logPaintTimer=0;
