function serverModal(instance,file=null){modal(`${closeButton()}<h2>${file?'Изменить сервер':'Добавить сервер'}</h2><form id="serverForm"><label>Название<input id="serverName" value="${esc(file?.name||'')}" maxlength="100" required></label><label>Адрес / IP<input id="serverAddress" value="${esc(file?.address||'')}" maxlength="255" required placeholder="example.org:25565"></label><div class="form-actions"><button type="submit" class="primary">Сохранить</button></div></form>`);$('#serverForm').onsubmit=e=>{e.preventDefault();run(async()=>{await api('serverAction',{instanceId:instance.id,operation:file?'edit':'add',index:file?.index??-1,name:$('#serverName').value.trim(),address:$('#serverAddress').value.trim()});$('#modal').close();renderEditor();});};}
function renderLibraryFiles(instance,kind,files){
 const selectable=['mods','shaders','resources','screenshots'].includes(kind), selected=new Set();
 const toolbar=$('#editorContent .toolbar');toolbar.insertAdjacentHTML('beforeend',`<input id="fileSearch" placeholder="Поиск…" aria-label="Поиск файлов">${['mods','shaders','resources'].includes(kind)?'<button id="enableSelected" disabled>Включить выбранные</button><button id="disableSelected" disabled>Отключить выбранные</button>':kind==='screenshots'?'<button id="copySelected" disabled>Копировать</button>':kind==='servers'?'<button id="addServer">Добавить сервер</button>':kind==='worlds'?'<button id="importWorld">Добавить мир</button>':''}${selectable?'<span class="muted" id="selectionCount">Выбрано: 0</span>':''}`);
 const content=files.length?kind==='screenshots'?`<div class="screenshots">${files.map((f,index)=>`<figure class="screenshot" data-select="${index}" data-search="${esc(f.name.toLowerCase())}">${image(f.image)}<figcaption>${esc(f.name)}</figcaption><button data-view-shot="${index}">Открыть</button><button data-rename-shot="${index}">Переименовать</button></figure>`).join('')}</div>`:`<div class="panel">${files.map((f,index)=>`<div class="file-row" ${selectable?`data-select="${index}"`:''} data-search="${esc(((f.label||f.name||'')+' '+(f.address||'')).toLowerCase())}"><div class="catalog-icon">${image(f.icon?.startsWith('data:')||f.icon?.startsWith('https:')?f.icon:f.icon?'data:image/png;base64,'+f.icon:'')||'◈'}</div><div class="details"><h3>${esc(f.label||f.name)}</h3><p class="muted">${esc(f.version||f.address||'')} ${esc(f.game||'')} ${f.lastPlayed?'· '+date(f.lastPlayed):''}</p></div>${['mods','shaders','resources'].includes(kind)?`<button class="switch ${f.enabled?'':'off'}" data-toggle-file="${index}">${f.enabled?'Включён':'Отключён'}</button>`:`<button data-play-target="${index}">${kind==='servers'?'Подключиться':'Играть'}</button><button data-edit-item="${index}">Изменить</button><button data-delete-item="${index}">Удалить</button>`}</div>`).join('')}</div>`:empty('Здесь пока пусто','Добавьте файлы или создайте запись.');$('#fileList').innerHTML=content;
 function selectionChanged(){for(const row of $$('[data-select]'))row.classList.toggle('selected-file',selected.has(Number(row.dataset.select)));if($('#selectionCount'))$('#selectionCount').textContent='Выбрано: '+selected.size;for(const id of ['enableSelected','disableSelected','copySelected'])if($('#'+id))$('#'+id).disabled=!selected.size;}
 $('#fileSearch').oninput=()=>{const query=$('#fileSearch').value.trim().toLowerCase();$$('#fileList [data-search]').forEach(row=>{const show=row.dataset.search.includes(query);row.hidden=!show;if(!show&&row.dataset.select)selected.delete(Number(row.dataset.select));});selectionChanged();};
 if(selectable)bindFileSelection($('#fileList'),selected,selectionChanged);
 async function enable(paths,enabled){await api('enableFiles',{instanceId:instance.id,kind,paths,enabled});renderEditor();}
 if($('#enableSelected'))$('#enableSelected').onclick=()=>run(()=>enable([...selected].map(n=>files[n].path),true));if($('#disableSelected'))$('#disableSelected').onclick=()=>run(()=>enable([...selected].map(n=>files[n].path),false));
 $$('[data-toggle-file]').forEach(b=>b.onclick=()=>run(()=>{const f=files[Number(b.dataset.toggleFile)];return enable([f.path],!f.enabled);}));
 if($('#copySelected'))$('#copySelected').onclick=()=>run(async()=>{await api('copyScreenshots',{instanceId:instance.id,paths:[...selected].map(n=>files[n].path)});toast(selected.size===1?'Изображение скопировано':'Файлы скопированы');});
 $$('[data-rename-shot]').forEach(b=>b.onclick=()=>{const f=files[Number(b.dataset.renameShot)];editText('Переименовать скриншот',f.name,name=>api('renameScreenshot',{instanceId:instance.id,path:f.path,name}));});
 $$('[data-view-shot]').forEach(b=>b.onclick=()=>screenshotViewer(files[Number(b.dataset.viewShot)].image));
 $$('.screenshot img').forEach(img=>img.ondblclick=()=>screenshotViewer(img.src));
 if($('#addServer'))$('#addServer').onclick=()=>serverModal(instance);
 if($('#importWorld'))$('#importWorld').onclick=()=>run(async()=>{await api('worldAction',{instanceId:instance.id,operation:'import'});renderEditor();});
 $$('[data-edit-item]').forEach(b=>b.onclick=()=>{const f=files[Number(b.dataset.editItem)];if(kind==='servers')serverModal(instance,f);else editText('Название мира',f.name,name=>api('worldAction',{instanceId:instance.id,operation:'rename',path:f.path,name}));});
 $$('[data-delete-item]').forEach(b=>b.onclick=()=>{const f=files[Number(b.dataset.deleteItem)];confirmAction(kind==='servers'?'Удалить сервер?':'Удалить мир?',f.name,async()=>{await api(kind==='servers'?'serverAction':'worldAction',{instanceId:instance.id,operation:'delete',index:f.index,path:f.path});renderEditor();});});
 $$('[data-play-target]').forEach(b=>b.onclick=()=>run(async()=>{const f=files[Number(b.dataset.playTarget)];if(state.running.includes(instance.id)||busy.has(instance.id))throw Error('Закройте текущую игру перед новым запуском');busy.add(instance.id);syncPlayButtons();openEditor(instance.id,'logs');try{updateState(await api('launchTarget',{instanceId:instance.id,kind,target:kind==='servers'?f.address:f.path}));}finally{busy.delete(instance.id);syncPlayButtons();}}));
}
let activeFileSelection=null;
document.addEventListener('pointerdown',e=>{
 if(e.button!==0||!activeFileSelection)return;
 const {host,clear}=activeFileSelection;
 if(!host.isConnected){activeFileSelection=null;return;}
 if(!host.contains(e.target)&&!e.target.closest('button,input,select,textarea,a,[role="button"],#modal'))clear();
});
function bindFileSelection(host,selected,changed){
 activeFileSelection={host,clear:()=>{selected.clear();changed();}};
 let anchor=null,frame=0,rectangle=null;const rows=[...host.querySelectorAll('[data-select]')];
 host.onpointerdown=e=>{if(e.button!==0||e.target.closest('button,input'))return;const row=e.target.closest('[data-select]');const wasSelected=row&&selected.has(Number(row.dataset.select));const before=new Set(e.ctrlKey?selected:[]);anchor={x:e.clientX,y:e.clientY,before,index:row?Number(row.dataset.select):null,moved:false};if(!e.ctrlKey&&!wasSelected)selected.clear();if(row){const index=Number(row.dataset.select);if(wasSelected)selected.delete(index);else selected.add(index);}changed();};
 host.onpointermove=e=>{if(!anchor)return;const x=e.clientX,y=e.clientY;if(Math.abs(x-anchor.x)+Math.abs(y-anchor.y)<5&&!anchor.moved)return;anchor.moved=true;host.setPointerCapture(e.pointerId);if(frame)cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{frame=0;if(!anchor)return;const bounds={left:Math.min(x,anchor.x),top:Math.min(y,anchor.y),right:Math.max(x,anchor.x),bottom:Math.max(y,anchor.y)};if(!rectangle){rectangle=document.createElement('div');rectangle.className='selection-box';document.body.append(rectangle);}Object.assign(rectangle.style,{left:bounds.left+'px',top:bounds.top+'px',width:bounds.right-bounds.left+'px',height:bounds.bottom-bounds.top+'px'});selected.clear();for(const n of anchor.before)selected.add(n);for(const row of rows){if(row.hidden)continue;const r=row.getBoundingClientRect();if(r.left<bounds.right&&r.right>bounds.left&&r.top<bounds.bottom&&r.bottom>bounds.top)selected.add(Number(row.dataset.select));}changed();});};
 host.onpointerup=host.onpointercancel=()=>{if(frame)cancelAnimationFrame(frame);frame=0;anchor=null;rectangle?.remove();rectangle=null;};host.ondragstart=e=>e.preventDefault();
}

function screenshotViewer(src){
 modal(`${closeButton()}<div class="screenshot-viewer" id="shotViewport">${image(src,'shot-image')}</div><p class="muted">Нажмите для приближения. Зажмите мышь, чтобы переместить изображение. Нажмите ещё раз, чтобы уменьшить.</p>`);
 $('#modal').classList.add('screenshot-dialog');
 const stage=$('#shotViewport'),img=stage.querySelector('img');let zoomed=false,x=0,y=0,drag=null;
 function paint(){const limitX=Math.max(0,(img.clientWidth*2.5-stage.clientWidth)/2),limitY=Math.max(0,(img.clientHeight*2.5-stage.clientHeight)/2);x=Math.max(-limitX,Math.min(limitX,x));y=Math.max(-limitY,Math.min(limitY,y));img.style.transform=`translate(${x}px,${y}px) scale(${zoomed?2.5:1})`;stage.classList.toggle('is-zoomed',zoomed);}
 stage.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();drag={id:e.pointerId,x:e.clientX,y:e.clientY,startX:x,startY:y,moved:false};stage.setPointerCapture(e.pointerId);};
 stage.onpointermove=e=>{if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>5)drag.moved=true;if(zoomed&&drag.moved){x=drag.startX+dx;y=drag.startY+dy;paint();}};
 stage.onpointerup=e=>{if(!drag||e.pointerId!==drag.id)return;if(!drag.moved){zoomed=!zoomed;x=0;y=0;if(zoomed){const r=stage.getBoundingClientRect();x=(r.left+r.width/2-e.clientX)*1.5;y=(r.top+r.height/2-e.clientY)*1.5;}paint();}drag=null;stage.releasePointerCapture(e.pointerId);};
 stage.onpointercancel=()=>{drag=null;};stage.ondragstart=e=>e.preventDefault();img.onload=paint;
}

